INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u2-C1','math',2,1,'u2',2,'여러 가지 도형 찾기 — 주변 물건과 그림에서 곧은 선으로 둘러싸인 모양과 둥근 모양을 찾고, 같은 모양끼리 모으며 삼각형·사각형·원으로 이름 붙이기',ARRAY['2수03-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u2-C2','math',2,1,'u2',2,'삼각형 — 곧은 선 3개로 둘러싸인 도형을 알고 변(곧은 선)·꼭짓점(곧은 선 2개가 만나는 점)을 세며, 놓인 방향·크기·생김이 달라도 삼각형을 찾기',ARRAY['2수03-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u2-C3','math',2,1,'u2',3,'사각형 — 곧은 선 4개로 둘러싸인 도형을 알고 변·꼭짓점을 세며, 기울어지거나 길쭉해도 사각형을 찾고 삼각형과 견주기',ARRAY['2수03-04']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u2-C4','math',2,1,'u2',4,'원 — 어느 쪽에서 보아도 똑같이 둥근 도형을 알고, 곧은 선과 꼭짓점이 없으며 크기가 달라도 원이고 길쭉한 모양은 원이 아님을 가르기',ARRAY['2수03-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u2-C5','math',2,1,'u2',5,'칠교판으로 모양 만들기 — 일곱 조각을 삼각형 5개·사각형 2개로 가르고, 조각을 변끼리 맞대어 겹치지 않게 놓아 도형과 여러 모양을 만들기',ARRAY['2수03-05']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u2-C6','math',2,1,'u2',6,'쌓은 모양과 위치 — 쌓기나무를 면과 면을 맞대어 반듯하게 쌓고, 내가 보는 쪽을 앞으로 하여 앞·뒤·오른쪽·왼쪽·위로 위치를 말하며 설명대로 쌓기',ARRAY['2수03-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u2-C7','math',2,1,'u2',7,'여러 가지 모양으로 쌓기 — 쌓기나무 3~6개로 여러 모양을 쌓고, 모양을 개수·층·방향으로 설명하며 두 모양의 같은 점과 다른 점 찾기',ARRAY['2수03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X01','math',2,'u2',ARRAY['M2-1-u2-C1','M2-1-u2-C2','M2-1-u2-C3']::text[],'한 곳이 끊어져 둘러싸이지 않은 모양도 곧은 선의 수만 맞으면 삼각형·사각형이라고 한다','손가락으로 선을 따라 한 바퀴 돌아 처음 자리로 돌아오는지 보기 — 끊어지면 도형이 아니다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X02','math',2,'u2',ARRAY['M2-1-u2-C1','M2-1-u2-C2','M2-1-u2-C3']::text[],'굽은 선이 섞인 모양도 뾰족한 곳의 수만 보고 삼각형·사각형이라고 한다','변 하나하나에 자를 대어 보기 — 자가 딱 붙지 않는 선은 곧은 선이 아니다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X03','math',2,'u2',ARRAY['M2-1-u2-C2','M2-1-u2-C3']::text[],'뒤집히거나 기울어진 삼각형·사각형은 그 도형이 아니라고 한다 — 꼭짓점이 아래로 간 삼각형, 비스듬한 사각형','종이 도형을 돌려 보며 변과 꼭짓점의 수가 그대로인 것을 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X04','math',2,'u2',ARRAY['M2-1-u2-C2','M2-1-u2-C3']::text[],'늘 보던 반듯한 모양만 그 도형이라고 한다 — 길쭉하거나 납작한 삼각형, 변의 길이가 다른 사각형을 빼놓음','「변이 몇 개, 꼭짓점이 몇 개」만 묻고, 길이·모양은 따지지 않게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X05','math',2,'u2',ARRAY['M2-1-u2-C2','M2-1-u2-C3']::text[],'변과 꼭짓점을 헷갈린다 — 곧은 선을 꼭짓점이라고, 만나는 점을 변이라고 함','변은 「선」이라 손가락으로 쓸고, 꼭짓점은 「점」이라 손가락으로 콕 찍기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X06','math',2,'u2',ARRAY['M2-1-u2-C1','M2-1-u2-C2','M2-1-u2-C3']::text[],'변·꼭짓점의 수를 잘못 세거나 삼각형(3)과 사각형(4)의 수를 바꾼다','한 꼭짓점에 표시하고 한 바퀴 돌며 번호를 붙여 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X07','math',2,'u2',ARRAY['M2-1-u2-C4']::text[],'한쪽으로 길쭉한 둥근 모양(달걀 모양)도 원이라고 한다','모양을 돌려 보며 「어느 쪽에서 보아도 똑같이 둥근지」 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X08','math',2,'u2',ARRAY['M2-1-u2-C1','M2-1-u2-C4']::text[],'원에도 곧은 선이나 꼭짓점이 있다고 하거나, 곧은 선이 섞인 둥근 모양을 원이라고 한다','원 둘레를 손가락으로 따라가며 꺾이는 곳·곧은 곳이 없음을 느끼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X09','math',2,'u2',ARRAY['M2-1-u2-C1','M2-1-u2-C2','M2-1-u2-C4']::text[],'도형을 크기·색·쓰임(무슨 물건인지)으로 가른다 — 큰 원과 작은 원을 다른 도형으로, 먹는 것은 삼각형이 아니라고','「모양만 본다」 — 크기와 물건 이름을 가리고 테두리만 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X10','math',2,'u2',ARRAY['M2-1-u2-C5']::text[],'칠교 조각을 잘못 가른다 — 사각형 조각을 1개로 세거나, 평행사변형 조각을 삼각형으로, 조각 크기가 다르면 다른 도형으로','조각마다 변을 세어 3이면 삼각형 통, 4이면 사각형 통에 넣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X11','math',2,'u2',ARRAY['M2-1-u2-C5','M2-1-u2-C6']::text[],'조각·쌓기나무를 겹치거나 띄워 놓고, 맞대는 변(면)을 바꾸면 다른 모양이 되는 것을 놓친다','변과 변(면과 면)을 딱 맞대어 겹치지도 띄우지도 않게 놓아 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X12','math',2,'u2',ARRAY['M2-1-u2-C6','M2-1-u2-C7']::text[],'쌓기나무를 셀 때 가려진 것을 빠뜨리거나 같은 것을 두 번 센다','1층부터 층별로 나누어 세고, 센 것에 표시하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X13','math',2,'u2',ARRAY['M2-1-u2-C6','M2-1-u2-C7']::text[],'오른쪽과 왼쪽을 바꾸어 말한다','내가 보는 쪽을 앞으로 두고, 오른손을 들어 오른쪽을 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X14','math',2,'u2',ARRAY['M2-1-u2-C6','M2-1-u2-C7']::text[],'앞과 뒤, 위와 아래를 헷갈리거나 위·옆을 바꾸어 쌓는다','내가 서 있는 쪽이 앞 — 그림의 ↘ 쪽이 앞, ↑ 쪽이 위임을 손으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X15','math',2,'u2',ARRAY['M2-1-u2-C6','M2-1-u2-C7']::text[],'쌓기나무의 개수와 층의 수를 헷갈리거나, 개수가 같으면 모양도 같다고 한다','개수는 하나하나, 층은 높이 — 같은 4개로 1층·2층 모양을 나란히 쌓아 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u2-X16','math',2,'u2',ARRAY['M2-1-u2-C1','M2-1-u2-C5','M2-1-u2-C7']::text[],'묻는 말을 거꾸로 읽거나 다른 것을 센다 — 아닌 것↔맞는 것, 변의 수 대신 도형의 수, 더 필요한 수 대신 전체 수','물음의 「아닌·몇 개·더」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_basic#1','math',2,1,'u2','L02','g2_1_math_u2_L02_basic','lesson_basic','M2-1-u2-C2',1,'mc','auto','삼각형은 어느 것인가요?',ARRAY['M2-1-u2-X01','M2-1-u2-X02']::text[],true,'{"seq":1,"concept":"M2-1-u2-C2","difficulty":1,"kind":"mc","stem":"삼각형은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M2-1-u2-X01"},{"t":"㉰","mis":"M2-1-u2-X02"}],"explanation":["삼각형은 곧은 선 3개로 둘러싸인 도형이에요.","㉮가 삼각형이에요.","㉯는 끊어진 곳이 있어요. ㉰는 굽은 선이 있어요."],"asset":{"type":"figs","items":["t1","o3","v3"]},"variant_rule":{"fig":{"ask":"which","target":"tri","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_basic#2','math',2,1,'u2','L02','g2_1_math_u2_L02_basic','lesson_basic','M2-1-u2-C2',1,'mc','auto','이 도형의 변은 모두 몇 개인가요?',ARRAY['M2-1-u2-X06']::text[],true,'{"seq":2,"concept":"M2-1-u2-C2","difficulty":1,"kind":"mc","stem":"이 도형의 변은 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-1-u2-X06"},{"t":"2","mis":"M2-1-u2-X06"}],"explanation":["도형을 둘러싼 곧은 선 하나하나가 변이에요.","이 도형은 삼각형이라 변이 3개예요.","한 곳에 손가락을 대고 한 바퀴 돌며 빠짐없이 세어요."],"asset":{"type":"figs","items":["t2"],"tag":false},"variant_rule":{"fnum":{"ask":"side","mis":{"count":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_basic#3','math',2,1,'u2','L02','g2_1_math_u2_L02_basic','lesson_basic','M2-1-u2-C2',1,'mc','auto','이 도형의 꼭짓점은 모두 몇 개인가요?',ARRAY['M2-1-u2-X06']::text[],true,'{"seq":3,"concept":"M2-1-u2-C2","difficulty":1,"kind":"mc","stem":"이 도형의 꼭짓점은 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-1-u2-X06"},{"t":"2","mis":"M2-1-u2-X06"}],"explanation":["곧은 선 2개가 만나는 점이 꼭짓점이에요.","이 도형은 삼각형이라 꼭짓점이 3개예요.","한 곳에 손가락을 대고 한 바퀴 돌며 빠짐없이 세어요."],"asset":{"type":"figs","items":["t4"],"tag":false},"variant_rule":{"fnum":{"ask":"vertex","mis":{"count":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_basic#4','math',2,1,'u2','L02','g2_1_math_u2_L02_basic','lesson_basic','M2-1-u2-C2',1,'mc','auto','곧은 선 2개가 만나는 점을 무엇이라고 하나요?',ARRAY['M2-1-u2-X05']::text[],true,'{"seq":4,"concept":"M2-1-u2-C2","difficulty":1,"kind":"mc","stem":"곧은 선 2개가 만나는 점을 무엇이라고 하나요?","options":[{"t":"꼭짓점","correct":true},{"t":"변","mis":"M2-1-u2-X05"},{"t":"곧은 선","mis":"M2-1-u2-X05"}],"explanation":["도형을 둘러싼 곧은 선 하나하나는 변이에요.","곧은 선 2개가 만나는 점은 꼭짓점이에요.","변은 「선」, 꼭짓점은 「점」이에요."],"variant_rule":{"alt":[{"stem":"삼각형을 둘러싼 곧은 선 하나하나를 무엇이라고 하나요?","options":[{"t":"변","correct":true},{"t":"꼭짓점","mis":"M2-1-u2-X05"},{"t":"뾰족한 곳","mis":"M2-1-u2-X05"}],"explanation":["삼각형은 곧은 선 3개로 둘러싸여 있어요.","그 곧은 선 하나하나를 변이라고 해요.","꼭짓점은 변 2개가 만나는 점이에요."]},{"stem":"삼각형은 곧은 선 몇 개로 둘러싸인 도형인가요?","options":[{"t":"3개","correct":true},{"t":"4개","mis":"M2-1-u2-X06"},{"t":"2개","mis":"M2-1-u2-X06"}],"explanation":["삼각형의 「삼」은 셋이라는 뜻이에요.","삼각형은 곧은 선 3개로 둘러싸인 도형이에요.","곧은 선 2개로는 둘러쌀 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_basic#5','math',2,1,'u2','L02','g2_1_math_u2_L02_basic','lesson_basic','M2-1-u2-C1',2,'mc','auto','삼각형 모양을 찾을 수 있는 물건은 어느 것인가요?',ARRAY['M2-1-u2-X09','M2-1-u2-X06']::text[],true,'{"seq":5,"concept":"M2-1-u2-C1","difficulty":2,"kind":"mc","stem":"삼각형 모양을 찾을 수 있는 물건은 어느 것인가요?","options":[{"t":"삼각김밥의 앞면","correct":true},{"t":"동전의 앞면","mis":"M2-1-u2-X09"},{"t":"공책의 표지","mis":"M2-1-u2-X06"}],"explanation":["물건의 테두리 모양만 봐요.","삼각김밥의 앞면은 곧은 선 3개로 둘러싸여 있어요.","동전은 둥글고, 공책 표지는 곧은 선이 4개예요."],"variant_rule":{"alt":[{"stem":"원 모양을 찾을 수 있는 물건은 어느 것인가요?","options":[{"t":"시계의 앞면","correct":true},{"t":"옷걸이","mis":"M2-1-u2-X08"},{"t":"칠판","mis":"M2-1-u2-X08"}],"explanation":["물건의 테두리 모양만 봐요.","둥근 시계의 앞면은 어느 쪽에서 보아도 똑같이 둥글어요.","옷걸이와 칠판에는 곧은 선이 있어요."]},{"stem":"사각형 모양을 찾을 수 있는 물건은 어느 것인가요?","options":[{"t":"달력의 한 장","correct":true},{"t":"접시의 바닥","mis":"M2-1-u2-X09"},{"t":"삼각자","mis":"M2-1-u2-X06"}],"explanation":["물건의 테두리 모양만 봐요.","달력 한 장은 곧은 선 4개로 둘러싸여 있어요.","접시는 둥글고, 삼각자는 곧은 선이 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_basic#6','math',2,1,'u2','L02','g2_1_math_u2_L02_basic','lesson_basic','M2-1-u2-C2',2,'mc','auto','삼각형이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u2-X04']::text[],true,'{"seq":6,"concept":"M2-1-u2-C2","difficulty":2,"kind":"mc","stem":"삼각형이 아닌 것은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M2-1-u2-X04"},{"t":"㉯","mis":"M2-1-u2-X04"},{"t":"㉰","mis":"M2-1-u2-X04"}],"explanation":["삼각형은 곧은 선 3개로 둘러싸인 도형이에요.","㉱는 끊어진 곳이 있어요 — 그래서 삼각형이 아니에요.","기울어지거나 길쭉해도 곧은 선 3개로 둘러싸이면 모두 삼각형이에요."],"asset":{"type":"figs","items":["t1","t3","t5","o5"]},"variant_rule":{"fig":{"ask":"not","target":"tri","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_basic#7','math',2,1,'u2','L02','g2_1_math_u2_L02_basic','lesson_basic','M2-1-u2-C2',2,'ox','auto','크기와 생김이 달라도 변이 3개, 꼭짓점이 3개이면 모두 삼각형이에요.',ARRAY['M2-1-u2-X09']::text[],true,'{"seq":7,"concept":"M2-1-u2-C2","difficulty":2,"kind":"ox","stem":"크기와 생김이 달라도 변이 3개, 꼭짓점이 3개이면 모두 삼각형이에요.","answer":"O","reason_options":[{"t":"곧은 선 3개로 둘러싸이면 삼각형이니까","correct":true},{"t":"크기가 같아야 같은 도형이니까","mis":"M2-1-u2-X09"}],"mis":"M2-1-u2-X09","explanation":["삼각형은 곧은 선 3개로 둘러싸인 도형이에요.","크기나 길쭉한 정도는 따지지 않아요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"뒤집어 놓은 삼각형(▽)은 삼각형이 아니에요.","answer":"X","reason_options":[{"t":"뒤집어도 곧은 선 3개로 둘러싸여 있으니까","correct":true},{"t":"뾰족한 곳이 위에 있어야 삼각형이니까","mis":"M2-1-u2-X03"}],"explanation":["뒤집어 놓아도 변은 3개, 꼭짓점은 3개예요.","놓인 방향은 따지지 않아요.","그래서 틀린 말이에요."]},{"stem":"길쭉하고 뾰족한 모양도 곧은 선 3개로 둘러싸여 있으면 삼각형이에요.","answer":"O","reason_options":[{"t":"곧은 선 3개로 둘러싸였으니까","correct":true},{"t":"반듯한 모양만 삼각형이니까","mis":"M2-1-u2-X04"}],"explanation":["삼각형은 곧은 선 3개로 둘러싸인 도형이에요.","길쭉해도 변과 꼭짓점이 3개씩이에요.","그래서 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_basic#8','math',2,1,'u2','L02','g2_1_math_u2_L02_basic','lesson_basic','M2-1-u2-C2',2,'mc','auto','그림에서 삼각형은 모두 몇 개인가요?',ARRAY['M2-1-u2-X01','M2-1-u2-X04']::text[],true,'{"seq":8,"concept":"M2-1-u2-C2","difficulty":2,"kind":"mc","stem":"그림에서 삼각형은 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-1-u2-X01"},{"t":"2","mis":"M2-1-u2-X04"}],"explanation":["삼각형은 곧은 선 3개로 둘러싸인 도형이에요.","㉮, ㉱, ㉳ — 모두 3개예요.","끊어진 곳이 있거나 굽은 선이 있으면 삼각형이 아니에요."],"asset":{"type":"figs","items":["t2","q1","o3","t6","v3","t3"]},"variant_rule":{"fig":{"ask":"count","target":"tri","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"},"n":6}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_basic#9','math',2,1,'u2','L02','g2_1_math_u2_L02_basic','lesson_basic','M2-1-u2-C1',2,'match','auto','설명에 알맞은 도형의 이름을 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-1-u2-C1","difficulty":2,"kind":"match","stem":"설명에 알맞은 도형의 이름을 이어 보세요.","pairs":[{"l":"곧은 선 3개로 둘러싸인 도형","r":"삼각형"},{"l":"곧은 선 4개로 둘러싸인 도형","r":"사각형"},{"l":"어느 쪽에서 보아도 똑같이 둥근 도형","r":"원"}],"mis":"M2-1-u2-X06","explanation":["곧은 선이 몇 개인지 먼저 세어요.","3개는 삼각형, 4개는 사각형이에요.","곧은 선이 없이 똑같이 둥글면 원이에요."],"variant_rule":{"alt":[{"stem":"물건과 그 테두리 모양을 이어 보세요.","pairs":[{"l":"삼각김밥의 앞면","r":"삼각형"},{"l":"달력의 한 장","r":"사각형"},{"l":"동전의 앞면","r":"원"}],"explanation":["물건의 테두리만 봐요.","삼각김밥은 곧은 선 3개, 달력은 곧은 선 4개로 둘러싸여 있어요.","동전은 어느 쪽에서 보아도 똑같이 둥글어요."]},{"stem":"도형과 변의 수를 이어 보세요.","pairs":[{"l":"삼각형","r":"변 3개"},{"l":"사각형","r":"변 4개"},{"l":"원","r":"변이 없어요"}],"explanation":["변은 도형을 둘러싼 곧은 선이에요.","삼각형은 3개, 사각형은 4개예요.","원에는 곧은 선이 없어서 변이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_basic#10','math',2,1,'u2','L02','g2_1_math_u2_L02_basic','lesson_basic','M2-1-u2-C2',3,'error','auto','친구들이 삼각형에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u2-X03','M2-1-u2-X06','M2-1-u2-X04']::text[],true,'{"seq":10,"concept":"M2-1-u2-C2","difficulty":3,"kind":"error","stem":"친구들이 삼각형에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우: 꼭짓점이 아래로 가게 뒤집으면 삼각형이 아니야.","correct":true,"mis_target":"M2-1-u2-X03"},{"t":"하린: 삼각형은 변이 3개, 꼭짓점이 3개야.","mis":"M2-1-u2-X06"},{"t":"도윤: 길쭉하게 그려도 곧은 선 3개로 둘러싸이면 삼각형이야.","mis":"M2-1-u2-X04"}],"explanation":["삼각형은 곧은 선 3개로 둘러싸인 도형이에요.","뒤집어도 변과 꼭짓점의 수는 그대로예요.","은우가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 삼각형에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아: 한 곳이 조금 떨어져 있어도 곧은 선이 3개면 삼각형이야.","correct":true,"mis_target":"M2-1-u2-X01"},{"t":"준우: 삼각형의 꼭짓점은 3개야.","mis":"M2-1-u2-X06"},{"t":"라희: 크기가 달라도 삼각형이야.","mis":"M2-1-u2-X09"}],"explanation":["삼각형은 곧은 선 3개로 「둘러싸인」 도형이에요.","떨어진 곳이 있으면 둘러싸이지 않아요.","서아가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_challenge#1','math',2,1,'u2','L02','g2_1_math_u2_L02_challenge','lesson_challenge','M2-1-u2-C2',2,'mc','auto','삼각형은 어느 것인가요?',ARRAY['M2-1-u2-X06','M2-1-u2-X01','M2-1-u2-X02']::text[],true,'{"seq":1,"concept":"M2-1-u2-C2","difficulty":2,"kind":"mc","stem":"삼각형은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M2-1-u2-X06"},{"t":"㉰","mis":"M2-1-u2-X01"},{"t":"㉱","mis":"M2-1-u2-X02"}],"explanation":["삼각형은 곧은 선 3개로 둘러싸인 도형이에요.","㉯가 삼각형이에요.","㉮는 변이 4개예요. ㉰는 끊어진 곳이 있어요. ㉱는 굽은 선이 있어요."],"asset":{"type":"figs","items":["q4","t5","o5","v3"]},"variant_rule":{"fig":{"ask":"which","target":"tri","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_challenge#2','math',2,1,'u2','L02','g2_1_math_u2_L02_challenge','lesson_challenge','M2-1-u2-C2',2,'sa','auto','이 도형의 꼭짓점은 모두 몇 개인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u2-C2","difficulty":2,"kind":"sa","stem":"이 도형의 꼭짓점은 모두 몇 개인가요?","answer":["3","3개"],"explanation":["곧은 선 2개가 만나는 점이 꼭짓점이에요.","이 도형은 삼각형이라 꼭짓점이 3개예요.","한 곳에 손가락을 대고 한 바퀴 돌며 빠짐없이 세어요."],"asset":{"type":"figs","items":["t6"],"tag":false},"variant_rule":{"fnum":{"ask":"vertex","mis":{"count":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_challenge#3','math',2,1,'u2','L02','g2_1_math_u2_L02_challenge','lesson_challenge','M2-1-u2-C2',3,'mc','auto','그림에서 삼각형은 모두 몇 개인가요?',ARRAY['M2-1-u2-X01','M2-1-u2-X04']::text[],true,'{"seq":3,"concept":"M2-1-u2-C2","difficulty":3,"kind":"mc","stem":"그림에서 삼각형은 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-1-u2-X01"},{"t":"2","mis":"M2-1-u2-X04"}],"explanation":["삼각형은 곧은 선 3개로 둘러싸인 도형이에요.","㉮, ㉰, ㉳ — 모두 3개예요.","끊어진 곳이 있거나 굽은 선이 있으면 삼각형이 아니에요."],"asset":{"type":"figs","items":["t4","o3","t1","q6","v3","t5","o5"]},"variant_rule":{"fig":{"ask":"count","target":"tri","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"},"n":7}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_challenge#4','math',2,1,'u2','L02','g2_1_math_u2_L02_challenge','lesson_challenge','M2-1-u2-C2',3,'mc','auto','삼각형이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u2-X04']::text[],true,'{"seq":4,"concept":"M2-1-u2-C2","difficulty":3,"kind":"mc","stem":"삼각형이 아닌 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M2-1-u2-X04"},{"t":"㉯","mis":"M2-1-u2-X04"},{"t":"㉱","mis":"M2-1-u2-X04"}],"explanation":["삼각형은 곧은 선 3개로 둘러싸인 도형이에요.","㉰는 굽은 선이 있어요 — 그래서 삼각형이 아니에요.","기울어지거나 길쭉해도 곧은 선 3개로 둘러싸이면 모두 삼각형이에요."],"asset":{"type":"figs","items":["t2","t6","v3","t4"]},"variant_rule":{"fig":{"ask":"not","target":"tri","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_challenge#5','math',2,1,'u2','L02','g2_1_math_u2_L02_challenge','lesson_challenge','M2-1-u2-C2',3,'ox','auto','삼각형에는 변이 3개, 꼭짓점이 4개 있어요.',ARRAY['M2-1-u2-X06']::text[],true,'{"seq":5,"concept":"M2-1-u2-C2","difficulty":3,"kind":"ox","stem":"삼각형에는 변이 3개, 꼭짓점이 4개 있어요.","answer":"X","reason_options":[{"t":"꼭짓점도 3개니까","correct":true},{"t":"꼭짓점은 변보다 하나 많으니까","mis":"M2-1-u2-X06"}],"mis":"M2-1-u2-X06","explanation":["곧은 선 2개가 만나는 곳마다 꼭짓점이 하나씩 생겨요.","삼각형은 변 3개, 꼭짓점 3개예요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"변 3개 가운데 하나가 굽은 선이어도 삼각형이에요.","answer":"X","reason_options":[{"t":"변은 모두 곧은 선이어야 하니까","correct":true},{"t":"선이 3개면 되니까","mis":"M2-1-u2-X02"}],"explanation":["삼각형은 「곧은」 선 3개로 둘러싸인 도형이에요.","굽은 선이 하나라도 있으면 삼각형이 아니에요.","그래서 틀린 말이에요."]},{"stem":"삼각형의 꼭짓점은 곧은 선 2개가 만나는 점이에요.","answer":"O","reason_options":[{"t":"변 2개가 만나는 곳이 꼭짓점이니까","correct":true},{"t":"곧은 선 하나하나가 꼭짓점이니까","mis":"M2-1-u2-X05"}],"explanation":["곧은 선 하나하나는 변이에요.","변 2개가 만나는 점이 꼭짓점이에요.","그래서 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_challenge#6','math',2,1,'u2','L02','g2_1_math_u2_L02_challenge','lesson_challenge','M2-1-u2-C1',3,'mc','auto','곧은 선이 하나도 없는 도형을 모두 고른 것은 어느 것인가요?',ARRAY['M2-1-u2-X07','M2-1-u2-X16']::text[],true,'{"seq":6,"concept":"M2-1-u2-C1","difficulty":3,"kind":"mc","stem":"곧은 선이 하나도 없는 도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉯, ㉱","correct":true},{"t":"㉯","mis":"M2-1-u2-X07"},{"t":"㉮, ㉰","mis":"M2-1-u2-X16"}],"explanation":["㉮와 ㉰는 곧은 선으로 둘러싸여 있어요.","㉯와 ㉱는 둥근 선으로만 되어 있어요 — ㉯는 원, ㉱는 길쭉한 모양이에요.","길쭉한 ㉱는 원은 아니지만 곧은 선은 없어요."],"asset":{"type":"figs","items":["t3","c2","q5","e1"]},"variant_rule":{"alt":[{"stem":"곧은 선으로만 둘러싸인 도형을 모두 고른 것은 어느 것인가요?","options":[{"t":"㉮, ㉱","correct":true},{"t":"㉮","mis":"M2-1-u2-X06"},{"t":"㉯, ㉰","mis":"M2-1-u2-X16"}],"explanation":["㉮는 곧은 선 3개, ㉱는 곧은 선 4개로 둘러싸여 있어요.","㉯는 둥글고, ㉰는 굽은 선이 섞여 있어요.","그래서 ㉮와 ㉱예요."],"asset":{"type":"figs","items":["t2","c1","v4","q2"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_challenge#7','math',2,1,'u2','L02','g2_1_math_u2_L02_challenge','lesson_challenge','M2-1-u2-C2',3,'error','auto','친구들이 삼각형을 그렸어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u2-X01','M2-1-u2-X04','M2-1-u2-X03']::text[],true,'{"seq":7,"concept":"M2-1-u2-C2","difficulty":3,"kind":"error","stem":"친구들이 삼각형을 그렸어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린: 점 3개를 이었는데 한 곳을 덜 이어 끝이 떨어졌어. 그래도 삼각형이야.","correct":true,"mis_target":"M2-1-u2-X01"},{"t":"도윤: 길쭉하게 그려도 변이 3개면 삼각형이야.","mis":"M2-1-u2-X04"},{"t":"서아: 기울여 그려도 삼각형이야.","mis":"M2-1-u2-X03"}],"explanation":["삼각형은 곧은 선 3개로 「둘러싸여」 있어야 해요.","끝이 떨어지면 둘러싸이지 않아 삼각형이 아니에요.","하린이가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 삼각형을 그렸어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호: 변 하나를 둥글게 그려도 삼각형이야.","correct":true,"mis_target":"M2-1-u2-X02"},{"t":"나은: 크게 그려도 작게 그려도 삼각형이야.","mis":"M2-1-u2-X09"},{"t":"시우: 꼭짓점이 3개 생겼어.","mis":"M2-1-u2-X06"}],"explanation":["삼각형의 변은 모두 곧은 선이에요.","둥근 선이 섞이면 삼각형이 아니에요.","지호가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_challenge#8','math',2,1,'u2','L02','g2_1_math_u2_L02_challenge','lesson_challenge','M2-1-u2-C2',4,'mc','auto','선을 따라 모두 자르면 삼각형은 몇 개 생기나요?',ARRAY['M2-1-u2-X16','M2-1-u2-X06']::text[],true,'{"seq":8,"concept":"M2-1-u2-C2","difficulty":4,"kind":"mc","stem":"선을 따라 모두 자르면 삼각형은 몇 개 생기나요?","options":[{"t":"2","correct":true},{"t":"3","mis":"M2-1-u2-X16"},{"t":"1","mis":"M2-1-u2-X06"}],"explanation":["잘라서 생기는 조각은 모두 3개예요.","그 가운데 변이 3개인 삼각형은 2개예요.","조각 하나하나의 곧은 선을 세어 이름을 정해요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[2,0],[0,4]]},{"p":[[2,0],[2,4],[0,4]]},{"p":[[2,0],[4,0],[4,4],[2,4]]}],"cut":true},"variant_rule":{"cut":{"target":"tri","mis":{"all":"X16","other":"X06","near":"X11"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_challenge#9','math',2,1,'u2','L02','g2_1_math_u2_L02_challenge','lesson_challenge','M2-1-u2-C2',4,'mc','auto','그림에서 삼각형은 모두 몇 개인가요?',ARRAY['M2-1-u2-X01','M2-1-u2-X04']::text[],true,'{"seq":9,"concept":"M2-1-u2-C2","difficulty":4,"kind":"mc","stem":"그림에서 삼각형은 모두 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"5","mis":"M2-1-u2-X01"},{"t":"3","mis":"M2-1-u2-X04"}],"explanation":["삼각형은 곧은 선 3개로 둘러싸인 도형이에요.","㉮, ㉰, ㉳, ㉵ — 모두 4개예요.","끊어진 곳이 있거나 굽은 선이 있으면 삼각형이 아니에요."],"asset":{"type":"figs","items":["t1","o3","t5","v3","q3","t6","o5","t2"]},"variant_rule":{"fig":{"ask":"count","target":"tri","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"},"n":8}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L02_challenge#10','math',2,1,'u2','L02','g2_1_math_u2_L02_challenge','lesson_challenge','M2-1-u2-C2',4,'essay','teacher','이 도형이 삼각형이 아닌 까닭을 쓰고, 삼각형이 되도록 고치는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u2-C2","difficulty":4,"kind":"essay","stem":"이 도형이 삼각형이 아닌 까닭을 쓰고, 삼각형이 되도록 고치는 방법을 설명해 보세요.","answer_guide":{"answer":"한 곳이 끊어져 있어 곧은 선으로 둘러싸여 있지 않기 때문이다. 끊어진 두 끝을 곧은 선으로 이어 주면 곧은 선 3개로 둘러싸인 삼각형이 된다.","scoring_points":["끊어져 둘러싸여 있지 않다는 까닭을 썼는가","끊어진 곳을 곧은 선으로 잇는 방법을 썼는가","고친 뒤 변 3개·꼭짓점 3개가 된다는 것을 말했는가"]},"explanation":["도형을 손가락으로 따라가면 처음 자리로 돌아오지 못해요.","끊어진 곳을 곧은 선으로 이으면 둘러싸여요.","그러면 곧은 선 3개로 둘러싸인 삼각형이 돼요."],"asset":{"type":"figs","items":["o3"],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_basic#1','math',2,1,'u2','L03','g2_1_math_u2_L03_basic','lesson_basic','M2-1-u2-C3',1,'mc','auto','사각형은 어느 것인가요?',ARRAY['M2-1-u2-X06','M2-1-u2-X01']::text[],true,'{"seq":1,"concept":"M2-1-u2-C3","difficulty":1,"kind":"mc","stem":"사각형은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M2-1-u2-X06"},{"t":"㉰","mis":"M2-1-u2-X01"}],"explanation":["사각형은 곧은 선 4개로 둘러싸인 도형이에요.","㉯가 사각형이에요.","㉮는 변이 3개예요. ㉰는 끊어진 곳이 있어요."],"asset":{"type":"figs","items":["t1","q1","o4"]},"variant_rule":{"fig":{"ask":"which","target":"quad","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_basic#2','math',2,1,'u2','L03','g2_1_math_u2_L03_basic','lesson_basic','M2-1-u2-C3',1,'mc','auto','이 도형의 변은 모두 몇 개인가요?',ARRAY['M2-1-u2-X06']::text[],true,'{"seq":2,"concept":"M2-1-u2-C3","difficulty":1,"kind":"mc","stem":"이 도형의 변은 모두 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M2-1-u2-X06"},{"t":"5","mis":"M2-1-u2-X06"}],"explanation":["도형을 둘러싼 곧은 선 하나하나가 변이에요.","이 도형은 사각형이라 변이 4개예요.","한 곳에 손가락을 대고 한 바퀴 돌며 빠짐없이 세어요."],"asset":{"type":"figs","items":["q2"],"tag":false},"variant_rule":{"fnum":{"ask":"side","mis":{"count":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_basic#3','math',2,1,'u2','L03','g2_1_math_u2_L03_basic','lesson_basic','M2-1-u2-C3',1,'mc','auto','이 도형의 꼭짓점은 모두 몇 개인가요?',ARRAY['M2-1-u2-X06']::text[],true,'{"seq":3,"concept":"M2-1-u2-C3","difficulty":1,"kind":"mc","stem":"이 도형의 꼭짓점은 모두 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M2-1-u2-X06"},{"t":"5","mis":"M2-1-u2-X06"}],"explanation":["곧은 선 2개가 만나는 점이 꼭짓점이에요.","이 도형은 사각형이라 꼭짓점이 4개예요.","한 곳에 손가락을 대고 한 바퀴 돌며 빠짐없이 세어요."],"asset":{"type":"figs","items":["q5"],"tag":false},"variant_rule":{"fnum":{"ask":"vertex","mis":{"count":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_basic#4','math',2,1,'u2','L03','g2_1_math_u2_L03_basic','lesson_basic','M2-1-u2-C3',1,'mc','auto','사각형은 곧은 선 몇 개로 둘러싸인 도형인가요?',ARRAY['M2-1-u2-X06']::text[],true,'{"seq":4,"concept":"M2-1-u2-C3","difficulty":1,"kind":"mc","stem":"사각형은 곧은 선 몇 개로 둘러싸인 도형인가요?","options":[{"t":"4개","correct":true},{"t":"3개","mis":"M2-1-u2-X06"},{"t":"5개","mis":"M2-1-u2-X06"}],"explanation":["사각형의 「사」는 넷이라는 뜻이에요.","사각형은 곧은 선 4개로 둘러싸인 도형이에요.","곧은 선 3개면 삼각형이에요."],"variant_rule":{"alt":[{"stem":"삼각형과 사각형 가운데 꼭짓점이 더 많은 도형은 어느 것인가요?","options":[{"t":"사각형","correct":true},{"t":"삼각형","mis":"M2-1-u2-X06"},{"t":"둘이 같아요","mis":"M2-1-u2-X06"}],"explanation":["삼각형의 꼭짓점은 3개예요.","사각형의 꼭짓점은 4개예요.","그래서 사각형이 1개 더 많아요."]},{"stem":"사각형의 변과 꼭짓점의 수를 바르게 말한 것은 어느 것인가요?","options":[{"t":"변 4개, 꼭짓점 4개","correct":true},{"t":"변 4개, 꼭짓점 3개","mis":"M2-1-u2-X06"},{"t":"변 3개, 꼭짓점 4개","mis":"M2-1-u2-X06"}],"explanation":["사각형은 곧은 선 4개로 둘러싸여 있어요.","변 2개가 만나는 곳마다 꼭짓점 — 4개예요.","변과 꼭짓점의 수가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_basic#5','math',2,1,'u2','L03','g2_1_math_u2_L03_basic','lesson_basic','M2-1-u2-C3',2,'mc','auto','사각형이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u2-X04']::text[],true,'{"seq":5,"concept":"M2-1-u2-C3","difficulty":2,"kind":"mc","stem":"사각형이 아닌 것은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M2-1-u2-X04"},{"t":"㉯","mis":"M2-1-u2-X04"},{"t":"㉰","mis":"M2-1-u2-X04"}],"explanation":["사각형은 곧은 선 4개로 둘러싸인 도형이에요.","㉱는 굽은 선이 있어요 — 그래서 사각형이 아니에요.","기울어지거나 길쭉해도 곧은 선 4개로 둘러싸이면 모두 사각형이에요."],"asset":{"type":"figs","items":["q1","q3","q6","v4"]},"variant_rule":{"fig":{"ask":"not","target":"quad","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_basic#6','math',2,1,'u2','L03','g2_1_math_u2_L03_basic','lesson_basic','M2-1-u2-C3',2,'mc','auto','그림에서 사각형은 모두 몇 개인가요?',ARRAY['M2-1-u2-X01','M2-1-u2-X04']::text[],true,'{"seq":6,"concept":"M2-1-u2-C3","difficulty":2,"kind":"mc","stem":"그림에서 사각형은 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-1-u2-X01"},{"t":"2","mis":"M2-1-u2-X04"}],"explanation":["사각형은 곧은 선 4개로 둘러싸인 도형이에요.","㉮, ㉰, ㉲ — 모두 3개예요.","끊어진 곳이 있거나 굽은 선이 있으면 사각형이 아니에요."],"asset":{"type":"figs","items":["q2","t3","q7","o4","q4","c2"]},"variant_rule":{"fig":{"ask":"count","target":"quad","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"},"n":6}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_basic#7','math',2,1,'u2','L03','g2_1_math_u2_L03_basic','lesson_basic','M2-1-u2-C3',2,'ox','auto','비스듬히 놓인 ◇ 모양도 곧은 선 4개로 둘러싸여 있으면 사각형이에요.',ARRAY['M2-1-u2-X03']::text[],true,'{"seq":7,"concept":"M2-1-u2-C3","difficulty":2,"kind":"ox","stem":"비스듬히 놓인 ◇ 모양도 곧은 선 4개로 둘러싸여 있으면 사각형이에요.","answer":"O","reason_options":[{"t":"곧은 선 4개로 둘러싸였으니까","correct":true},{"t":"반듯하게 놓여야 사각형이니까","mis":"M2-1-u2-X03"}],"mis":"M2-1-u2-X03","explanation":["사각형은 곧은 선 4개로 둘러싸인 도형이에요.","돌려 놓아도 변과 꼭짓점은 4개씩이에요.","그래서 맞는 말이에요."],"variant_rule":{"alt":[{"stem":"네 변의 길이가 모두 같아야 사각형이에요.","answer":"X","reason_options":[{"t":"곧은 선 4개로 둘러싸이기만 하면 되니까","correct":true},{"t":"네 변이 같아야 반듯하니까","mis":"M2-1-u2-X04"}],"explanation":["사각형은 곧은 선 4개로 둘러싸인 도형이에요.","변의 길이는 따지지 않아요 — 길쭉한 사각형도 있어요.","그래서 틀린 말이에요."]},{"stem":"사각형의 꼭짓점은 곧은 선 4개가 한꺼번에 만나는 점이에요.","answer":"X","reason_options":[{"t":"꼭짓점은 곧은 선 2개가 만나는 점이니까","correct":true},{"t":"사각형은 곧은 선이 4개니까","mis":"M2-1-u2-X05"}],"explanation":["꼭짓점은 곧은 선 2개가 만나는 점이에요.","사각형에는 그런 점이 4개 있어요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_basic#8','math',2,1,'u2','L03','g2_1_math_u2_L03_basic','lesson_basic','M2-1-u2-C3',2,'mc','auto','사각형 모양을 찾을 수 없는 물건은 어느 것인가요?',ARRAY['M2-1-u2-X16']::text[],true,'{"seq":8,"concept":"M2-1-u2-C3","difficulty":2,"kind":"mc","stem":"사각형 모양을 찾을 수 없는 물건은 어느 것인가요?","options":[{"t":"동전의 앞면","correct":true},{"t":"공책의 표지","mis":"M2-1-u2-X16"},{"t":"칠판","mis":"M2-1-u2-X16"}],"explanation":["「찾을 수 없는」 것을 묻고 있어요.","공책 표지와 칠판은 곧은 선 4개로 둘러싸여 있어요.","동전의 앞면은 둥글어서 사각형이 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 사각형 모양을 찾을 수 없는 물건은 어느 것인가요?","options":[{"t":"삼각김밥의 앞면","correct":true},{"t":"창문","mis":"M2-1-u2-X16"},{"t":"스케치북","mis":"M2-1-u2-X16"}],"explanation":["「찾을 수 없는」 것을 묻고 있어요.","창문과 스케치북은 곧은 선 4개로 둘러싸여 있어요.","삼각김밥의 앞면은 곧은 선이 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_basic#9','math',2,1,'u2','L03','g2_1_math_u2_L03_basic','lesson_basic','M2-1-u2-C3',2,'mc','auto','삼각형 1개와 사각형 2개가 있어요. 꼭짓점은 모두 몇 개인가요?',ARRAY['M2-1-u2-X06','M2-1-u2-X16']::text[],true,'{"seq":9,"concept":"M2-1-u2-C3","difficulty":2,"kind":"mc","stem":"삼각형 1개와 사각형 2개가 있어요. 꼭짓점은 모두 몇 개인가요?","options":[{"t":"11","correct":true},{"t":"10","mis":"M2-1-u2-X06"},{"t":"3","mis":"M2-1-u2-X16"}],"explanation":["삼각형 하나에 꼭짓점이 3개, 사각형 하나에 4개예요.","3씩 1번은 3, 4씩 2번은 8 — 모두 11개예요.","도형의 수가 아니라 꼭짓점의 수를 세요."],"variant_rule":{"fnum":{"ask":"sum","mis":{"swap":"X06","shapes":"X16"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_basic#10','math',2,1,'u2','L03','g2_1_math_u2_L03_basic','lesson_basic','M2-1-u2-C3',3,'mc','auto','선을 따라 모두 자르면 사각형은 몇 개 생기나요?',ARRAY['M2-1-u2-X16','M2-1-u2-X11']::text[],true,'{"seq":10,"concept":"M2-1-u2-C3","difficulty":3,"kind":"mc","stem":"선을 따라 모두 자르면 사각형은 몇 개 생기나요?","options":[{"t":"2","correct":true},{"t":"4","mis":"M2-1-u2-X16"},{"t":"3","mis":"M2-1-u2-X11"}],"explanation":["잘라서 생기는 조각은 모두 4개예요.","그 가운데 변이 4개인 사각형은 2개예요.","조각 하나하나의 곧은 선을 세어 이름을 정해요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[4,0],[0,2]]},{"p":[[4,0],[4,2],[0,2]]},{"p":[[0,2],[2,2],[2,4],[0,4]]},{"p":[[2,2],[4,2],[4,4],[2,4]]}],"cut":true},"variant_rule":{"cut":{"target":"quad","mis":{"all":"X16","other":"X06","near":"X11"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_challenge#1','math',2,1,'u2','L03','g2_1_math_u2_L03_challenge','lesson_challenge','M2-1-u2-C3',2,'mc','auto','사각형은 어느 것인가요?',ARRAY['M2-1-u2-X06','M2-1-u2-X02','M2-1-u2-X01']::text[],true,'{"seq":1,"concept":"M2-1-u2-C3","difficulty":2,"kind":"mc","stem":"사각형은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M2-1-u2-X06"},{"t":"㉯","mis":"M2-1-u2-X02"},{"t":"㉱","mis":"M2-1-u2-X01"}],"explanation":["사각형은 곧은 선 4개로 둘러싸인 도형이에요.","㉰가 사각형이에요.","㉮는 변이 5개예요. ㉯는 굽은 선이 있어요. ㉱는 끊어진 곳이 있어요."],"asset":{"type":"figs","items":["p5","v5","q6","o3"]},"variant_rule":{"fig":{"ask":"which","target":"quad","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_challenge#2','math',2,1,'u2','L03','g2_1_math_u2_L03_challenge','lesson_challenge','M2-1-u2-C3',2,'sa','auto','이 도형의 꼭짓점은 모두 몇 개인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u2-C3","difficulty":2,"kind":"sa","stem":"이 도형의 꼭짓점은 모두 몇 개인가요?","answer":["4","4개"],"explanation":["곧은 선 2개가 만나는 점이 꼭짓점이에요.","이 도형은 사각형이라 꼭짓점이 4개예요.","한 곳에 손가락을 대고 한 바퀴 돌며 빠짐없이 세어요."],"asset":{"type":"figs","items":["q3"],"tag":false},"variant_rule":{"fnum":{"ask":"vertex","mis":{"count":"X06"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_challenge#3','math',2,1,'u2','L03','g2_1_math_u2_L03_challenge','lesson_challenge','M2-1-u2-C3',3,'mc','auto','그림에서 사각형은 모두 몇 개인가요?',ARRAY['M2-1-u2-X02','M2-1-u2-X04']::text[],true,'{"seq":3,"concept":"M2-1-u2-C3","difficulty":3,"kind":"mc","stem":"그림에서 사각형은 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-1-u2-X02"},{"t":"2","mis":"M2-1-u2-X04"}],"explanation":["사각형은 곧은 선 4개로 둘러싸인 도형이에요.","㉮, ㉱, ㉳ — 모두 3개예요.","끊어진 곳이 있거나 굽은 선이 있으면 사각형이 아니에요."],"asset":{"type":"figs","items":["q3","t2","v4","q5","h6","q7","o4"]},"variant_rule":{"fig":{"ask":"count","target":"quad","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"},"n":7}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_challenge#4','math',2,1,'u2','L03','g2_1_math_u2_L03_challenge','lesson_challenge','M2-1-u2-C3',3,'mc','auto','사각형이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u2-X04']::text[],true,'{"seq":4,"concept":"M2-1-u2-C3","difficulty":3,"kind":"mc","stem":"사각형이 아닌 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M2-1-u2-X04"},{"t":"㉯","mis":"M2-1-u2-X04"},{"t":"㉱","mis":"M2-1-u2-X04"}],"explanation":["사각형은 곧은 선 4개로 둘러싸인 도형이에요.","㉰는 끊어진 곳이 있어요 — 그래서 사각형이 아니에요.","기울어지거나 길쭉해도 곧은 선 4개로 둘러싸이면 모두 사각형이에요."],"asset":{"type":"figs","items":["q4","q2","o4","q5"]},"variant_rule":{"fig":{"ask":"not","target":"quad","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_challenge#5','math',2,1,'u2','L03','g2_1_math_u2_L03_challenge','lesson_challenge','M2-1-u2-C3',3,'mc','auto','삼각형 3개와 사각형 2개가 있어요. 변은 모두 몇 개인가요?',ARRAY['M2-1-u2-X06','M2-1-u2-X16']::text[],true,'{"seq":5,"concept":"M2-1-u2-C3","difficulty":3,"kind":"mc","stem":"삼각형 3개와 사각형 2개가 있어요. 변은 모두 몇 개인가요?","options":[{"t":"17","correct":true},{"t":"18","mis":"M2-1-u2-X06"},{"t":"5","mis":"M2-1-u2-X16"}],"explanation":["삼각형 하나에 변이 3개, 사각형 하나에 4개예요.","3씩 3번은 9, 4씩 2번은 8 — 모두 17개예요.","도형의 수가 아니라 변의 수를 세요."],"variant_rule":{"fnum":{"ask":"sum","mis":{"swap":"X06","shapes":"X16"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_challenge#6','math',2,1,'u2','L03','g2_1_math_u2_L03_challenge','lesson_challenge','M2-1-u2-C3',3,'error','auto','친구들이 사각형에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u2-X04','M2-1-u2-X06','M2-1-u2-X03']::text[],true,'{"seq":6,"concept":"M2-1-u2-C3","difficulty":3,"kind":"error","stem":"친구들이 사각형에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온: 사각형은 네 변의 길이가 모두 같아야 해.","correct":true,"mis_target":"M2-1-u2-X04"},{"t":"나은: 사각형은 꼭짓점이 4개야.","mis":"M2-1-u2-X06"},{"t":"세아: 비스듬히 놓아도 사각형이야.","mis":"M2-1-u2-X03"}],"explanation":["사각형은 곧은 선 4개로 둘러싸인 도형이에요.","변의 길이는 서로 달라도 돼요.","라온이가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 사각형에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤: 사각형은 꼭짓점이 3개, 변이 4개야.","correct":true,"mis_target":"M2-1-u2-X06"},{"t":"시우: 길쭉한 사각형도 있어.","mis":"M2-1-u2-X04"},{"t":"은우: 사각형의 변은 모두 곧은 선이야.","mis":"M2-1-u2-X02"}],"explanation":["사각형은 변 4개, 꼭짓점 4개예요.","변과 꼭짓점의 수가 같아요.","하윤이가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_challenge#7','math',2,1,'u2','L03','g2_1_math_u2_L03_challenge','lesson_challenge','M2-1-u2-C3',3,'mc','auto','삼각형과 사각형의 같은 점은 어느 것인가요?',ARRAY['M2-1-u2-X06']::text[],true,'{"seq":7,"concept":"M2-1-u2-C3","difficulty":3,"kind":"mc","stem":"삼각형과 사각형의 같은 점은 어느 것인가요?","options":[{"t":"곧은 선으로 둘러싸여 있어요.","correct":true},{"t":"꼭짓점의 수가 같아요.","mis":"M2-1-u2-X06"},{"t":"변의 수가 같아요.","mis":"M2-1-u2-X06"}],"explanation":["삼각형은 곧은 선 3개, 사각형은 곧은 선 4개로 둘러싸여 있어요.","둘 다 곧은 선으로 둘러싸인 도형이에요.","변과 꼭짓점의 수는 달라요."],"variant_rule":{"alt":[{"stem":"삼각형과 사각형의 다른 점은 어느 것인가요?","options":[{"t":"꼭짓점의 수가 달라요.","correct":true},{"t":"사각형에만 곧은 선이 있어요.","mis":"M2-1-u2-X02"},{"t":"삼각형에는 꼭짓점이 없어요.","mis":"M2-1-u2-X05"}],"explanation":["두 도형 모두 곧은 선으로 둘러싸여 있어요.","삼각형의 꼭짓점은 3개, 사각형의 꼭짓점은 4개예요.","그래서 꼭짓점(과 변)의 수가 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_challenge#8','math',2,1,'u2','L03','g2_1_math_u2_L03_challenge','lesson_challenge','M2-1-u2-C3',4,'mc','auto','선을 따라 모두 자르면 사각형은 몇 개 생기나요?',ARRAY['M2-1-u2-X16','M2-1-u2-X11']::text[],true,'{"seq":8,"concept":"M2-1-u2-C3","difficulty":4,"kind":"mc","stem":"선을 따라 모두 자르면 사각형은 몇 개 생기나요?","options":[{"t":"2","correct":true},{"t":"4","mis":"M2-1-u2-X16"},{"t":"3","mis":"M2-1-u2-X11"}],"explanation":["잘라서 생기는 조각은 모두 4개예요.","그 가운데 변이 4개인 사각형은 2개예요.","조각 하나하나의 곧은 선을 세어 이름을 정해요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[2,0],[2,2],[0,2]]},{"p":[[2,0],[4,0],[2,2]]},{"p":[[4,0],[4,2],[2,2]]},{"p":[[4,0],[6,0],[6,2],[4,2]]}],"cut":true},"variant_rule":{"cut":{"target":"quad","mis":{"all":"X16","other":"X06","near":"X11"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_challenge#9','math',2,1,'u2','L03','g2_1_math_u2_L03_challenge','lesson_challenge','M2-1-u2-C3',4,'mc','auto','그림에서 사각형은 모두 몇 개인가요?',ARRAY['M2-1-u2-X01','M2-1-u2-X04']::text[],true,'{"seq":9,"concept":"M2-1-u2-C3","difficulty":4,"kind":"mc","stem":"그림에서 사각형은 모두 몇 개인가요?","options":[{"t":"4","correct":true},{"t":"5","mis":"M2-1-u2-X01"},{"t":"3","mis":"M2-1-u2-X04"}],"explanation":["사각형은 곧은 선 4개로 둘러싸인 도형이에요.","㉮, ㉰, ㉳, ㉵ — 모두 4개예요.","끊어진 곳이 있거나 굽은 선이 있으면 사각형이 아니에요."],"asset":{"type":"figs","items":["q6","o4","q2","v5","t4","q4","p5","q1"]},"variant_rule":{"fig":{"ask":"count","target":"quad","mis":{"open":"X01","curve":"X02","near":"X06","atyp":"X04"},"n":8}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L03_challenge#10','math',2,1,'u2','L03','g2_1_math_u2_L03_challenge','lesson_challenge','M2-1-u2-C3',4,'essay','teacher','삼각형과 사각형의 같은 점과 다른 점을 변과 꼭짓점으로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u2-C3","difficulty":4,"kind":"essay","stem":"삼각형과 사각형의 같은 점과 다른 점을 변과 꼭짓점으로 설명해 보세요.","answer_guide":{"answer":"같은 점: 둘 다 곧은 선으로 둘러싸여 있고 변과 꼭짓점이 있다. 다른 점: 삼각형은 변 3개·꼭짓점 3개, 사각형은 변 4개·꼭짓점 4개이다.","scoring_points":["같은 점(곧은 선으로 둘러싸임)을 썼는가","다른 점(변·꼭짓점의 수 3과 4)을 썼는가","변과 꼭짓점이라는 말을 바르게 썼는가"]},"explanation":["둘 다 곧은 선으로 둘러싸인 도형이에요.","삼각형은 3개씩, 사각형은 4개씩 — 변과 꼭짓점의 수가 달라요.","각 도형 안에서는 변과 꼭짓점의 수가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_basic#1','math',2,1,'u2','L04','g2_1_math_u2_L04_basic','lesson_basic','M2-1-u2-C4',1,'mc','auto','원은 어느 것인가요?',ARRAY['M2-1-u2-X08']::text[],true,'{"seq":1,"concept":"M2-1-u2-C4","difficulty":1,"kind":"mc","stem":"원은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M2-1-u2-X08"},{"t":"㉰","mis":"M2-1-u2-X08"}],"explanation":["원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","㉮가 원이에요.","㉯는 곧은 선과 꼭짓점이 있어요. ㉰는 곧은 선과 꼭짓점이 있어요."],"asset":{"type":"figs","items":["c1","t3","q1"]},"variant_rule":{"fig":{"ask":"which","target":"circle","mis":{"ellipse":"X07","curve":"X08","near":"X08","atyp":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_basic#2','math',2,1,'u2','L04','g2_1_math_u2_L04_basic','lesson_basic','M2-1-u2-C4',1,'mc','auto','원에는 곧은 선이 몇 개 있나요?',ARRAY['M2-1-u2-X08']::text[],true,'{"seq":2,"concept":"M2-1-u2-C4","difficulty":1,"kind":"mc","stem":"원에는 곧은 선이 몇 개 있나요?","options":[{"t":"없어요","correct":true},{"t":"1개","mis":"M2-1-u2-X08"},{"t":"4개","mis":"M2-1-u2-X08"}],"explanation":["원은 둥근 선으로만 되어 있어요.","그래서 곧은 선이 하나도 없어요.","원에는 꼭짓점도 없어요."],"variant_rule":{"alt":[{"stem":"원에는 꼭짓점이 몇 개 있나요?","options":[{"t":"없어요","correct":true},{"t":"1개","mis":"M2-1-u2-X08"},{"t":"3개","mis":"M2-1-u2-X08"}],"explanation":["꼭짓점은 곧은 선 2개가 만나는 점이에요.","원에는 곧은 선이 없어서 꼭짓점도 없어요.","원은 뾰족한 곳이 없이 둥글어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_basic#3','math',2,1,'u2','L04','g2_1_math_u2_L04_basic','lesson_basic','M2-1-u2-C4',1,'mc','auto','원 모양을 찾을 수 있는 물건은 어느 것인가요?',ARRAY['M2-1-u2-X08']::text[],true,'{"seq":3,"concept":"M2-1-u2-C4","difficulty":1,"kind":"mc","stem":"원 모양을 찾을 수 있는 물건은 어느 것인가요?","options":[{"t":"동전의 앞면","correct":true},{"t":"공책의 표지","mis":"M2-1-u2-X08"},{"t":"옷걸이","mis":"M2-1-u2-X08"}],"explanation":["물건의 테두리 모양만 봐요.","동전의 앞면은 어느 쪽에서 보아도 똑같이 둥글어요.","공책 표지와 옷걸이에는 곧은 선이 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원 모양을 찾을 수 있는 물건은 어느 것인가요?","options":[{"t":"접시의 바닥","correct":true},{"t":"창문","mis":"M2-1-u2-X08"},{"t":"럭비공","mis":"M2-1-u2-X07"}],"explanation":["물건의 테두리 모양만 봐요.","접시 바닥은 어느 쪽에서 보아도 똑같이 둥글어요.","창문은 곧은 선이 있고, 럭비공은 길쭉해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_basic#4','math',2,1,'u2','L04','g2_1_math_u2_L04_basic','lesson_basic','M2-1-u2-C4',1,'mc','auto','원은 어느 것인가요?',ARRAY['M2-1-u2-X07','M2-1-u2-X08']::text[],true,'{"seq":4,"concept":"M2-1-u2-C4","difficulty":1,"kind":"mc","stem":"원은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M2-1-u2-X07"},{"t":"㉰","mis":"M2-1-u2-X08"}],"explanation":["원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","㉯가 원이에요.","㉮는 한쪽으로 길쭉해요. ㉰는 곧은 선과 꼭짓점이 있어요."],"asset":{"type":"figs","items":["e2","c3","h6"]},"variant_rule":{"fig":{"ask":"which","target":"circle","mis":{"ellipse":"X07","curve":"X08","near":"X08","atyp":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_basic#5','math',2,1,'u2','L04','g2_1_math_u2_L04_basic','lesson_basic','M2-1-u2-C4',2,'mc','auto','원이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u2-X09']::text[],true,'{"seq":5,"concept":"M2-1-u2-C4","difficulty":2,"kind":"mc","stem":"원이 아닌 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M2-1-u2-X09"},{"t":"㉯","mis":"M2-1-u2-X09"},{"t":"㉱","mis":"M2-1-u2-X09"}],"explanation":["원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","㉰는 한쪽으로 길쭉해요 — 그래서 원이 아니에요.","크기가 달라도 똑같이 둥글면 모두 원이에요."],"asset":{"type":"figs","items":["c1","c2","e1","c3"]},"variant_rule":{"fig":{"ask":"not","target":"circle","mis":{"ellipse":"X07","curve":"X08","near":"X08","atyp":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_basic#6','math',2,1,'u2','L04','g2_1_math_u2_L04_basic','lesson_basic','M2-1-u2-C4',2,'mc','auto','그림에서 원은 모두 몇 개인가요?',ARRAY['M2-1-u2-X07','M2-1-u2-X09']::text[],true,'{"seq":6,"concept":"M2-1-u2-C4","difficulty":2,"kind":"mc","stem":"그림에서 원은 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-1-u2-X07"},{"t":"2","mis":"M2-1-u2-X09"}],"explanation":["원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","㉮, ㉰, ㉳ — 모두 3개예요.","길쭉하거나 곧은 선이 있으면 원이 아니에요."],"asset":{"type":"figs","items":["c2","e1","c1","d1","q3","c3"]},"variant_rule":{"fig":{"ask":"count","target":"circle","mis":{"ellipse":"X07","curve":"X08","near":"X08","atyp":"X09"},"n":6}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_basic#7','math',2,1,'u2','L04','g2_1_math_u2_L04_basic','lesson_basic','M2-1-u2-C4',2,'ox','auto','크기가 다른 두 원은 서로 다른 도형이에요.',ARRAY['M2-1-u2-X09']::text[],true,'{"seq":7,"concept":"M2-1-u2-C4","difficulty":2,"kind":"ox","stem":"크기가 다른 두 원은 서로 다른 도형이에요.","answer":"X","reason_options":[{"t":"크기가 달라도 똑같이 둥근 원이니까","correct":true},{"t":"크기가 다르면 다른 도형이니까","mis":"M2-1-u2-X09"}],"mis":"M2-1-u2-X09","explanation":["원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","크기는 따지지 않아요.","그래서 틀린 말이에요 — 둘 다 원이에요."],"variant_rule":{"alt":[{"stem":"달걀처럼 한쪽으로 길쭉한 둥근 모양은 원이 아니에요.","answer":"O","reason_options":[{"t":"어느 쪽에서 보아도 똑같이 둥글지 않으니까","correct":true},{"t":"둥근 모양은 모두 원이니까","mis":"M2-1-u2-X07"}],"explanation":["원은 어느 쪽에서 보아도 똑같이 둥글어요.","길쭉한 모양은 한쪽이 더 길어요.","그래서 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_basic#8','math',2,1,'u2','L04','g2_1_math_u2_L04_basic','lesson_basic','M2-1-u2-C4',2,'mc','auto','원에 대한 설명으로 바른 것은 어느 것인가요?',ARRAY['M2-1-u2-X08','M2-1-u2-X07']::text[],true,'{"seq":8,"concept":"M2-1-u2-C4","difficulty":2,"kind":"mc","stem":"원에 대한 설명으로 바른 것은 어느 것인가요?","options":[{"t":"어느 쪽에서 보아도 똑같이 둥글어요.","correct":true},{"t":"꼭짓점이 1개 있어요.","mis":"M2-1-u2-X08"},{"t":"길쭉해도 둥글면 원이에요.","mis":"M2-1-u2-X07"}],"explanation":["원은 둥근 선으로만 되어 있어요.","어느 쪽에서 보아도 똑같이 둥글어요.","꼭짓점이 없고, 길쭉하면 원이 아니에요."],"variant_rule":{"alt":[{"stem":"원에 대한 설명으로 틀린 것은 어느 것인가요?","options":[{"t":"변이 1개 있어요.","correct":true},{"t":"곧은 선이 없어요.","mis":"M2-1-u2-X16"},{"t":"크기가 달라도 원이에요.","mis":"M2-1-u2-X16"}],"explanation":["「틀린」 것을 묻고 있어요.","원에는 곧은 선이 없어서 변도 없어요.","곧은 선이 없다는 것과 크기가 달라도 원이라는 것은 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_basic#9','math',2,1,'u2','L04','g2_1_math_u2_L04_basic','lesson_basic','M2-1-u2-C4',2,'match','auto','도형과 변의 수를 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M2-1-u2-C4","difficulty":2,"kind":"match","stem":"도형과 변의 수를 이어 보세요.","pairs":[{"l":"삼각형","r":"변 3개"},{"l":"사각형","r":"변 4개"},{"l":"원","r":"변이 없어요"}],"mis":"M2-1-u2-X08","explanation":["변은 도형을 둘러싼 곧은 선이에요.","삼각형은 3개, 사각형은 4개예요.","원에는 곧은 선이 없어서 변이 없어요."],"variant_rule":{"alt":[{"stem":"도형과 꼭짓점의 수를 이어 보세요.","pairs":[{"l":"원","r":"꼭짓점이 없어요"},{"l":"삼각형","r":"꼭짓점 3개"},{"l":"사각형","r":"꼭짓점 4개"}],"explanation":["꼭짓점은 곧은 선 2개가 만나는 점이에요.","삼각형은 3개, 사각형은 4개예요.","원에는 곧은 선이 없어서 꼭짓점도 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_basic#10','math',2,1,'u2','L04','g2_1_math_u2_L04_basic','lesson_basic','M2-1-u2-C4',3,'error','auto','친구들이 원에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u2-X07','M2-1-u2-X08','M2-1-u2-X09']::text[],true,'{"seq":10,"concept":"M2-1-u2-C4","difficulty":3,"kind":"error","stem":"친구들이 원에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤: 달걀처럼 길쭉하게 둥근 모양도 원이야.","correct":true,"mis_target":"M2-1-u2-X07"},{"t":"하린: 원에는 꼭짓점이 없어.","mis":"M2-1-u2-X08"},{"t":"서아: 동전과 접시는 크기가 달라도 둘 다 원 모양이야.","mis":"M2-1-u2-X09"}],"explanation":["원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","달걀 모양은 한쪽으로 길쭉해서 원이 아니에요.","도윤이가 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 원에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준우: 원에는 둥근 꼭짓점이 1개 있어.","correct":true,"mis_target":"M2-1-u2-X08"},{"t":"라희: 원은 곧은 선이 없어.","mis":"M2-1-u2-X08"},{"t":"시우: 큰 원도 작은 원도 모두 원이야.","mis":"M2-1-u2-X09"}],"explanation":["꼭짓점은 곧은 선 2개가 만나는 점이에요.","원에는 곧은 선이 없어서 꼭짓점도 없어요.","준우가 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_challenge#1','math',2,1,'u2','L04','g2_1_math_u2_L04_challenge','lesson_challenge','M2-1-u2-C4',2,'mc','auto','원은 어느 것인가요?',ARRAY['M2-1-u2-X08','M2-1-u2-X07']::text[],true,'{"seq":1,"concept":"M2-1-u2-C4","difficulty":2,"kind":"mc","stem":"원은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M2-1-u2-X08"},{"t":"㉯","mis":"M2-1-u2-X07"},{"t":"㉰","mis":"M2-1-u2-X08"}],"explanation":["원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","㉱가 원이에요.","㉮는 곧은 선과 꼭짓점이 있어요. ㉯는 한쪽으로 길쭉해요. ㉰는 굽은 선이 있어요."],"asset":{"type":"figs","items":["q3","e1","d1","c2"]},"variant_rule":{"fig":{"ask":"which","target":"circle","mis":{"ellipse":"X07","curve":"X08","near":"X08","atyp":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_challenge#2','math',2,1,'u2','L04','g2_1_math_u2_L04_challenge','lesson_challenge','M2-1-u2-C4',2,'sa','auto','그림에서 원은 모두 몇 개인가요?','{}'::text[],true,'{"seq":2,"concept":"M2-1-u2-C4","difficulty":2,"kind":"sa","stem":"그림에서 원은 모두 몇 개인가요?","answer":["3","3개"],"explanation":["원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","㉮, ㉰, ㉲ — 모두 3개예요.","길쭉하거나 곧은 선이 있으면 원이 아니에요."],"asset":{"type":"figs","items":["c1","e2","c3","o4","c2"]},"variant_rule":{"fig":{"ask":"count","target":"circle","mis":{"ellipse":"X07","curve":"X08","near":"X08","atyp":"X09"},"n":5}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_challenge#3','math',2,1,'u2','L04','g2_1_math_u2_L04_challenge','lesson_challenge','M2-1-u2-C4',3,'mc','auto','원이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u2-X09']::text[],true,'{"seq":3,"concept":"M2-1-u2-C4","difficulty":3,"kind":"mc","stem":"원이 아닌 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M2-1-u2-X09"},{"t":"㉰","mis":"M2-1-u2-X09"},{"t":"㉱","mis":"M2-1-u2-X09"}],"explanation":["원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","㉯는 굽은 선이 있어요 — 그래서 원이 아니에요.","크기가 달라도 똑같이 둥글면 모두 원이에요."],"asset":{"type":"figs","items":["c3","d1","c1","c2"]},"variant_rule":{"fig":{"ask":"not","target":"circle","mis":{"ellipse":"X07","curve":"X08","near":"X08","atyp":"X09"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_challenge#4','math',2,1,'u2','L04','g2_1_math_u2_L04_challenge','lesson_challenge','M2-1-u2-C4',3,'mc','auto','그림에서 원은 모두 몇 개인가요?',ARRAY['M2-1-u2-X07','M2-1-u2-X09']::text[],true,'{"seq":4,"concept":"M2-1-u2-C4","difficulty":3,"kind":"mc","stem":"그림에서 원은 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-1-u2-X07"},{"t":"2","mis":"M2-1-u2-X09"}],"explanation":["원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","㉯, ㉱, ㉴ — 모두 3개예요.","길쭉하거나 곧은 선이 있으면 원이 아니에요."],"asset":{"type":"figs","items":["e1","c2","h6","c1","e2","d1","c3"]},"variant_rule":{"fig":{"ask":"count","target":"circle","mis":{"ellipse":"X07","curve":"X08","near":"X08","atyp":"X09"},"n":7}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_challenge#5','math',2,1,'u2','L04','g2_1_math_u2_L04_challenge','lesson_challenge','M2-1-u2-C4',3,'ox','auto','원은 둥근 변이 1개, 꼭짓점이 0개인 도형이에요.',ARRAY['M2-1-u2-X08']::text[],true,'{"seq":5,"concept":"M2-1-u2-C4","difficulty":3,"kind":"ox","stem":"원은 둥근 변이 1개, 꼭짓점이 0개인 도형이에요.","answer":"X","reason_options":[{"t":"원에는 곧은 선(변)이 없으니까","correct":true},{"t":"둥근 선 하나가 변이니까","mis":"M2-1-u2-X08"}],"mis":"M2-1-u2-X08","explanation":["변은 도형을 둘러싼 「곧은」 선이에요.","원은 둥근 선으로만 되어 있어 변이 없어요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","answer":"O","reason_options":[{"t":"원의 뜻이 그러니까","correct":true},{"t":"조금 길쭉해도 원이니까","mis":"M2-1-u2-X07"}],"explanation":["원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","길쭉하면 원이 아니에요.","그래서 맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_challenge#6','math',2,1,'u2','L04','g2_1_math_u2_L04_challenge','lesson_challenge','M2-1-u2-C4',3,'mc','auto','변과 꼭짓점의 수를 모두 더한 것이 가장 많은 도형은 어느 것인가요?',ARRAY['M2-1-u2-X06','M2-1-u2-X08']::text[],true,'{"seq":6,"concept":"M2-1-u2-C4","difficulty":3,"kind":"mc","stem":"변과 꼭짓점의 수를 모두 더한 것이 가장 많은 도형은 어느 것인가요?","options":[{"t":"사각형","correct":true},{"t":"삼각형","mis":"M2-1-u2-X06"},{"t":"원","mis":"M2-1-u2-X08"}],"explanation":["삼각형은 3 + 3 = 6, 사각형은 4 + 4 = 8이에요.","원은 변도 꼭짓점도 없어 0이에요.","그래서 사각형이 가장 많아요."],"variant_rule":{"alt":[{"stem":"변과 꼭짓점의 수를 모두 더한 것이 가장 적은 도형은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"삼각형","mis":"M2-1-u2-X08"},{"t":"사각형","mis":"M2-1-u2-X16"}],"explanation":["삼각형은 6, 사각형은 8이에요.","원은 변도 꼭짓점도 없어 0이에요.","그래서 원이 가장 적어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_challenge#7','math',2,1,'u2','L04','g2_1_math_u2_L04_challenge','lesson_challenge','M2-1-u2-C4',3,'mc','auto','모양을 본떠 그렸을 때 원이 되는 것은 어느 것인가요?',ARRAY['M2-1-u2-X07','M2-1-u2-X08']::text[],true,'{"seq":7,"concept":"M2-1-u2-C4","difficulty":3,"kind":"mc","stem":"모양을 본떠 그렸을 때 원이 되는 것은 어느 것인가요?","options":[{"t":"음료수 캔의 밑면","correct":true},{"t":"럭비공을 옆에서 본 모양","mis":"M2-1-u2-X07"},{"t":"지우개의 윗면","mis":"M2-1-u2-X08"}],"explanation":["본뜬 모양이 어느 쪽에서 보아도 똑같이 둥근지 봐요.","음료수 캔의 밑면은 원이에요.","럭비공은 길쭉하고, 지우개 윗면에는 곧은 선이 있어요."],"variant_rule":{"alt":[{"stem":"모양을 본떠 그렸을 때 원이 되지 않는 것은 어느 것인가요?","options":[{"t":"달걀을 옆에서 본 모양","correct":true},{"t":"컵의 밑면","mis":"M2-1-u2-X16"},{"t":"단추의 앞면","mis":"M2-1-u2-X16"}],"explanation":["「되지 않는」 것을 묻고 있어요.","컵 밑면과 단추는 똑같이 둥근 원이에요.","달걀은 한쪽으로 길쭉해서 원이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_challenge#8','math',2,1,'u2','L04','g2_1_math_u2_L04_challenge','lesson_challenge','M2-1-u2-C4',4,'mc','auto','원 2개, 삼각형 1개, 사각형 1개가 있어요. 꼭짓점은 모두 몇 개인가요?',ARRAY['M2-1-u2-X08','M2-1-u2-X16']::text[],true,'{"seq":8,"concept":"M2-1-u2-C4","difficulty":4,"kind":"mc","stem":"원 2개, 삼각형 1개, 사각형 1개가 있어요. 꼭짓점은 모두 몇 개인가요?","options":[{"t":"7","correct":true},{"t":"9","mis":"M2-1-u2-X08"},{"t":"4","mis":"M2-1-u2-X16"}],"explanation":["삼각형은 꼭짓점 3개, 사각형은 4개예요.","원에는 꼭짓점이 없어요 — 3 + 4 = 7개예요.","도형의 수(4개)가 아니라 꼭짓점의 수를 세요."],"variant_rule":{"alt":[{"stem":"원 3개, 삼각형 2개가 있어요. 변은 모두 몇 개인가요?","options":[{"t":"6","correct":true},{"t":"9","mis":"M2-1-u2-X08"},{"t":"5","mis":"M2-1-u2-X16"}],"explanation":["삼각형 하나에 변이 3개 — 2개면 6개예요.","원에는 변이 없어요.","그래서 변은 모두 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_challenge#9','math',2,1,'u2','L04','g2_1_math_u2_L04_challenge','lesson_challenge','M2-1-u2-C4',4,'mc','auto','그림에서 원은 모두 몇 개인가요?',ARRAY['M2-1-u2-X07','M2-1-u2-X09']::text[],true,'{"seq":9,"concept":"M2-1-u2-C4","difficulty":4,"kind":"mc","stem":"그림에서 원은 모두 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-1-u2-X07"},{"t":"2","mis":"M2-1-u2-X09"}],"explanation":["원은 어느 쪽에서 보아도 똑같이 둥근 도형이에요.","㉮, ㉰, ㉳ — 모두 3개예요.","길쭉하거나 곧은 선이 있으면 원이 아니에요."],"asset":{"type":"figs","items":["c1","e1","c2","q1","d1","c3","e2","t4"]},"variant_rule":{"fig":{"ask":"count","target":"circle","mis":{"ellipse":"X07","curve":"X08","near":"X08","atyp":"X09"},"n":8}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L04_challenge#10','math',2,1,'u2','L04','g2_1_math_u2_L04_challenge','lesson_challenge','M2-1-u2-C4',4,'essay','teacher','㉮와 ㉯ 가운데 원이 아닌 것을 고르고, 그 까닭을 원의 뜻을 넣어 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u2-C4","difficulty":4,"kind":"essay","stem":"㉮와 ㉯ 가운데 원이 아닌 것을 고르고, 그 까닭을 원의 뜻을 넣어 설명해 보세요.","answer_guide":{"answer":"㉯가 원이 아니다. 원은 어느 쪽에서 보아도 똑같이 둥근 도형인데, ㉯는 한쪽으로 길쭉해서 보는 쪽에 따라 길이가 다르기 때문이다.","scoring_points":["원이 아닌 도형을 바르게 골랐는가","원의 뜻(어느 쪽에서 보아도 똑같이 둥글다)을 썼는가","길쭉하다는 까닭을 들었는가"]},"explanation":["㉮는 어느 쪽에서 보아도 똑같이 둥글어요.","㉯는 옆으로 길쭉해요.","그래서 ㉯는 원이 아니에요."],"asset":{"type":"figs","items":["c3","e1"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L05_basic#1','math',2,1,'u2','L05','g2_1_math_u2_L05_basic','lesson_basic','M2-1-u2-C5',1,'mc','auto','①번 조각은 어떤 도형인가요?',ARRAY['M2-1-u2-X10']::text[],true,'{"seq":1,"concept":"M2-1-u2-C5","difficulty":1,"kind":"mc","stem":"①번 조각은 어떤 도형인가요?","options":[{"t":"삼각형","correct":true},{"t":"사각형","mis":"M2-1-u2-X10"},{"t":"원","mis":"M2-1-u2-X10"}],"explanation":["①번 조각의 곧은 선(변)을 세어 보세요.","변이 3개라서 삼각형이에요.","칠교 조각은 삼각형 5개, 사각형 2개예요."],"asset":{"type":"tiles","pieces":[{"n":"①","p":[[0,0],[4,0],[2,2]],"hi":true},{"n":"②","p":[[0,0],[2,2],[0,4]]},{"n":"③","p":[[4,2],[4,4],[2,4]]},{"n":"④","p":[[2,2],[3,3],[2,4],[1,3]]},{"n":"⑤","p":[[2,2],[3,1],[3,3]]},{"n":"⑥","p":[[4,0],[4,2],[3,3],[3,1]]},{"n":"⑦","p":[[1,3],[2,4],[0,4]]}]},"variant_rule":{"tan":{"ask":"kind","mis":{"kind":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L05_basic#2','math',2,1,'u2','L05','g2_1_math_u2_L05_basic','lesson_basic','M2-1-u2-C5',1,'mc','auto','④번 조각은 어떤 도형인가요?',ARRAY['M2-1-u2-X10']::text[],true,'{"seq":2,"concept":"M2-1-u2-C5","difficulty":1,"kind":"mc","stem":"④번 조각은 어떤 도형인가요?","options":[{"t":"사각형","correct":true},{"t":"삼각형","mis":"M2-1-u2-X10"},{"t":"원","mis":"M2-1-u2-X10"}],"explanation":["④번 조각의 곧은 선(변)을 세어 보세요.","변이 4개라서 사각형이에요.","칠교 조각은 삼각형 5개, 사각형 2개예요."],"asset":{"type":"tiles","pieces":[{"n":"①","p":[[0,0],[4,0],[2,2]]},{"n":"②","p":[[0,0],[2,2],[0,4]]},{"n":"③","p":[[4,2],[4,4],[2,4]]},{"n":"④","p":[[2,2],[3,3],[2,4],[1,3]],"hi":true},{"n":"⑤","p":[[2,2],[3,1],[3,3]]},{"n":"⑥","p":[[4,0],[4,2],[3,3],[3,1]]},{"n":"⑦","p":[[1,3],[2,4],[0,4]]}]},"variant_rule":{"tan":{"ask":"kind","mis":{"kind":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L05_basic#3','math',2,1,'u2','L05','g2_1_math_u2_L05_basic','lesson_basic','M2-1-u2-C5',1,'mc','auto','칠교판은 모두 몇 조각으로 되어 있나요?',ARRAY['M2-1-u2-X10']::text[],true,'{"seq":3,"concept":"M2-1-u2-C5","difficulty":1,"kind":"mc","stem":"칠교판은 모두 몇 조각으로 되어 있나요?","options":[{"t":"7조각","correct":true},{"t":"5조각","mis":"M2-1-u2-X10"},{"t":"2조각","mis":"M2-1-u2-X10"}],"explanation":["칠교판의 「칠」은 일곱이라는 뜻이에요.","칠교판은 7조각이에요.","삼각형 5조각과 사각형 2조각을 모두 세어요."],"variant_rule":{"alt":[{"stem":"칠교 조각 가운데 삼각형 조각은 몇 개인가요?","options":[{"t":"5개","correct":true},{"t":"2개","mis":"M2-1-u2-X16"},{"t":"7개","mis":"M2-1-u2-X10"}],"explanation":["조각마다 변을 세어요.","변이 3개인 삼각형 조각은 5개예요.","7개는 조각 전체의 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
