INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L05_basic#5','math',2,1,'u2','L05','g2_1_math_u2_L05_basic','lesson_basic','M2-1-u2-C5',2,'mc','auto','색칠한 조각 가운데 삼각형은 모두 몇 개인가요?',ARRAY['M2-1-u2-X16','M2-1-u2-X10']::text[],true,'{"seq":5,"concept":"M2-1-u2-C5","difficulty":2,"kind":"mc","stem":"색칠한 조각 가운데 삼각형은 모두 몇 개인가요?","options":[{"t":"2","correct":true},{"t":"4","mis":"M2-1-u2-X16"},{"t":"3","mis":"M2-1-u2-X10"}],"explanation":["색칠한 조각은 ① ④ ⑥ ⑦ — 4개예요.","그 가운데 삼각형은 ① ⑦ — 2개예요.","변이 3개인 조각만 세어요."],"asset":{"type":"tiles","pieces":[{"n":"①","p":[[0,0],[4,0],[2,2]],"hi":true},{"n":"②","p":[[0,0],[2,2],[0,4]]},{"n":"③","p":[[4,2],[4,4],[2,4]]},{"n":"④","p":[[2,2],[3,3],[2,4],[1,3]],"hi":true},{"n":"⑤","p":[[2,2],[3,1],[3,3]]},{"n":"⑥","p":[[4,0],[4,2],[3,3],[3,1]],"hi":true},{"n":"⑦","p":[[1,3],[2,4],[0,4]],"hi":true}]},"variant_rule":{"tan":{"ask":"hicount","target":"tri","mis":{"all":"X16","count":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L05_basic#6','math',2,1,'u2','L05','g2_1_math_u2_L05_basic','lesson_basic','M2-1-u2-C5',2,'mc','auto','색칠한 조각 가운데 사각형은 모두 몇 개인가요?',ARRAY['M2-1-u2-X16','M2-1-u2-X10']::text[],true,'{"seq":6,"concept":"M2-1-u2-C5","difficulty":2,"kind":"mc","stem":"색칠한 조각 가운데 사각형은 모두 몇 개인가요?","options":[{"t":"1","correct":true},{"t":"3","mis":"M2-1-u2-X16"},{"t":"2","mis":"M2-1-u2-X10"}],"explanation":["색칠한 조각은 ② ④ ⑤ — 3개예요.","그 가운데 사각형은 ④ — 1개예요.","변이 4개인 조각만 세어요."],"asset":{"type":"tiles","pieces":[{"n":"①","p":[[0,0],[4,0],[2,2]]},{"n":"②","p":[[0,0],[2,2],[0,4]],"hi":true},{"n":"③","p":[[4,2],[4,4],[2,4]]},{"n":"④","p":[[2,2],[3,3],[2,4],[1,3]],"hi":true},{"n":"⑤","p":[[2,2],[3,1],[3,3]],"hi":true},{"n":"⑥","p":[[4,0],[4,2],[3,3],[3,1]]},{"n":"⑦","p":[[1,3],[2,4],[0,4]]}]},"variant_rule":{"tan":{"ask":"hicount","target":"quad","mis":{"all":"X16","count":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L05_basic#7','math',2,1,'u2','L05','g2_1_math_u2_L05_basic','lesson_basic','M2-1-u2-C5',2,'mc','auto','칠교 조각 가운데 사각형 조각은 몇 개인가요?',ARRAY['M2-1-u2-X16','M2-1-u2-X10']::text[],true,'{"seq":7,"concept":"M2-1-u2-C5","difficulty":2,"kind":"mc","stem":"칠교 조각 가운데 사각형 조각은 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"5개","mis":"M2-1-u2-X16"},{"t":"1개","mis":"M2-1-u2-X10"}],"explanation":["변이 4개인 조각을 찾아요.","④번과 ⑥번 — 사각형 조각은 2개예요.","⑥번처럼 비스듬한 조각도 변이 4개라 사각형이에요."],"variant_rule":{"alt":[{"stem":"칠교 조각 가운데 꼭짓점이 3개인 조각은 몇 개인가요?","options":[{"t":"5개","correct":true},{"t":"2개","mis":"M2-1-u2-X16"},{"t":"3개","mis":"M2-1-u2-X10"}],"explanation":["꼭짓점이 3개인 조각은 삼각형이에요.","①②③⑤⑦ — 5개예요.","꼭짓점이 4개인 ④⑥은 사각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L05_basic#8','math',2,1,'u2','L05','g2_1_math_u2_L05_basic','lesson_basic','M2-1-u2-C5',2,'ox','auto','칠교 조각은 모두 크기가 같아요.',ARRAY['M2-1-u2-X10']::text[],true,'{"seq":8,"concept":"M2-1-u2-C5","difficulty":2,"kind":"ox","stem":"칠교 조각은 모두 크기가 같아요.","answer":"X","reason_options":[{"t":"큰 삼각형·작은 삼각형처럼 크기가 다르니까","correct":true},{"t":"모두 칠교 조각이니까","mis":"M2-1-u2-X10"}],"mis":"M2-1-u2-X10","explanation":["①②는 큰 삼각형, ⑤⑦은 작은 삼각형이에요.","칠교 조각은 크기가 서로 달라요.","그래서 틀린 말이에요."],"variant_rule":{"alt":[{"stem":"크기가 달라도 변이 3개인 칠교 조각은 모두 삼각형이에요.","answer":"O","reason_options":[{"t":"변이 3개면 삼각형이니까","correct":true},{"t":"크기가 같아야 같은 도형이니까","mis":"M2-1-u2-X10"}],"explanation":["①②③⑤⑦은 크기가 달라도 변이 3개예요.","그래서 모두 삼각형이에요.","맞는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u2_L05_basic#9','math',2,1,'u2','L05','g2_1_math_u2_L05_basic','lesson_basic','M2-1-u2-C5',2,'mc','auto','칠교 조각으로 모양을 만드는 바른 방법은 어느 것인가요?',ARRAY['M2-1-u2-X11']::text[],true,'{"seq":9,"concept":"M2-1-u2-C5","difficulty":2,"kind":"mc","stem":"칠교 조각으로 모양을 만드는 바른 방법은 어느 것인가요?","options":[{"t":"조각끼리 변을 맞대어 겹치지 않게 놓아요.","correct":true},{"t":"조각을 서로 겹쳐서 놓아요.","mis":"M2-1-u2-X11"},{"t":"조각 사이를 띄워서 놓아요.","mis":"M2-1-u2-X11"}],"explanation":["칠교 조각은 변과 변을 맞대어 붙여요.","겹치거나 띄우지 않고 빈틈없이 놓아요.","그래야 모양이 반듯하게 만들어져요."],"variant_rule":{"alt":[{"stem":"칠교 조각 두 개를 붙일 때 맞대는 곳은 어디인가요?","options":[{"t":"변과 변","correct":true},{"t":"꼭짓점과 꼭짓점만","mis":"M2-1-u2-X11"},{"t":"조각의 가운데","mis":"M2-1-u2-X11"}],"explanation":["조각끼리는 변을 맞대어 붙여요.","꼭짓점끼리만 닿으면 모양이 흔들려요.","변과 변을 딱 맞대어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
